BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
SELECT has_function('public','update_property',ARRAY['uuid','text','text','text','text','text','integer','integer','integer','integer','bigint','bigint','text[]','text','double precision','double precision'],'owner editor RPC exists');
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('66666666-0000-4000-8000-000000000001','editor-owner@test.local',now()),('66666666-0000-4000-8000-000000000002','editor-other@test.local',now());
SELECT set_config('request.jwt.claims','{"sub":"66666666-0000-4000-8000-000000000001"}',true);
CREATE TEMP TABLE f AS SELECT public.create_property('Editor apartment','Description','Cotroceni','Private original','apartment',50,2,1,2019,10000000,50000,'{}') j;
SELECT is(public.update_property((SELECT (j->>'id')::uuid FROM f),'Edited title','Edited description','Dorobanți','Private edited','apartment',60,3,2,2020,12000000,NULL,'{}')->>'title','Edited title','owner updates details');
SELECT is((SELECT price_minor FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='rent'),50000::bigint,'NULL price preserves existing listing');
SELECT is((SELECT price_minor FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='sale'),12000000::bigint,'positive price updates existing listing');
SELECT set_config('request.jwt.claims','{"sub":"66666666-0000-4000-8000-000000000002"}',true);
SELECT throws_ok(format('SELECT public.update_property(%L,''Other title'','''',''Cotroceni'',''Address'',''apartment'',50,2,1,2019,NULL,NULL,''{}'')',(SELECT j->>'id' FROM f)),'P0001','Owner required','unrelated user cannot edit');
SELECT ok(NOT public.media_write_allowed('66666666-0000-4000-8000-000000000001/image.webp'),'other owner media path blocked');
SELECT ok(public.media_write_allowed('66666666-0000-4000-8000-000000000002/image.webp'),'own verified media path allowed');
SELECT set_config('request.jwt.claims','{"sub":"66666666-0000-4000-8000-000000000001"}',true);
CREATE TEMP TABLE a AS SELECT public.start_auction((SELECT id FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='rent'),'ascending','public',now(),now()+interval '1 hour',1000,100) j;
SELECT throws_ok(format('SELECT public.update_property(%L,''Other title'','''',''Cotroceni'',''Address'',''apartment'',50,2,1,2019,NULL,NULL,''{}'')',(SELECT j->>'id' FROM f)),'P0001','Property already has an active auction','active auction blocks editing');
SELECT * FROM finish();
ROLLBACK;
